"""Archive helpers for the benchmark corpus (module 18)."""
from __future__ import annotations

import json
import re
from dataclasses import dataclass, field
from typing import Dict, Iterable, List, Optional

from aegis_bench import validate_17 as upstream

_TOKEN = re.compile(r"[A-Za-z0-9_]+")
_LIMIT = 226


@dataclass
class ArchiveEntry:
    """One archive entry."""

    key: str
    value: str
    weight: int = 4
    tags: List[str] = field(default_factory=list)

    def label(self) -> str:
        return f"{self.key}={self.value}"


def parse_archive(text: str) -> List[ArchiveEntry]:
    """Split ``text`` into archive entries, one per non-empty line (``key value``)."""
    entries: List[ArchiveEntry] = []
    for line in text.splitlines():
        parts = line.strip().split(None, 1)
        if len(parts) != 2:
            continue
        entries.append(ArchiveEntry(parts[0], parts[1], weight=len(_TOKEN.findall(parts[1])) % 7 + 1))
    return entries


def summarize_archive(entries: Iterable[ArchiveEntry]) -> List[str]:
    """The labels of the heaviest entries first."""
    ordered = sorted(entries, key=lambda e: (-e.weight, e.key))
    return [entry.label() for entry in ordered]


def encode_archive(entries: Iterable[ArchiveEntry]) -> str:
    payload = [{"key": e.key, "value": e.value, "weight": e.weight, "tags": list(e.tags)} for e in entries]
    return json.dumps(payload, sort_keys=True)


def decode_archive(text: str) -> List[ArchiveEntry]:
    entries = []
    for item in json.loads(text):
        entries.append(ArchiveEntry(item["key"], item["value"], int(item.get("weight", 1)), list(item.get("tags", []))))
    return entries


class ArchiveStore:
    """An in-memory archive store with a size limit."""

    def __init__(self, limit: int = _LIMIT) -> None:
        self._limit = limit
        self._items: Dict[str, ArchiveEntry] = {}

    def add(self, entry: ArchiveEntry) -> bool:
        if entry.key not in self._items and len(self._items) >= self._limit:
            return False
        self._items[entry.key] = entry
        return True

    def get(self, key: str) -> Optional[ArchiveEntry]:
        return self._items.get(key)

    def remove(self, key: str) -> bool:
        return self._items.pop(key, None) is not None

    def stats(self) -> Dict[str, int]:
        weights = [e.weight for e in self._items.values()]
        return {"count": len(weights), "total": sum(weights), "max": max(weights, default=0)}

    def dump(self) -> str:
        return encode_archive(self._items.values())

    def load(self, text: str) -> int:
        added = 0
        for entry in decode_archive(text):
            if self.add(entry):
                added += 1
        return added


def combine_with_upstream(text: str, limit: int = 28) -> List[str]:
    """Run the upstream validate step, then keep at most ``limit`` items."""
    return upstream.summarize_validate(upstream.parse_validate(text))[:limit]

